def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 98:
        return 'D'

    opp = [h[1] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')
    last_opp = opp[-1]

    if opp_def == 0:
        return 'C'

    if opp_def * 2 > n:
        return 'D'

    # Forgive a single early defection at round 2 (n=1)
    if opp_def == 1 and len(opp) > 1 and opp[1] == 'D' and opp[0] == 'C':
        return 'C'

    if last_opp == 'D':
        return 'D'
    else:
        return 'C'
